from ..ordering import out_of_order

def min_element(seq, first, last):
    """
    Returns the index of the minimum element in the range [first, last).
    """
    if first == last:
        return last
    min_index = first
    for i in range(first + 1, last):
        if out_of_order(seq[min_index],seq[i]):
            min_index = i
    return min_index

