from ..ordering import out_of_order

def lower_bound(a, first, last, value):
    """
    Returns the first index in [first, last) where value may be inserted.
    """
    while first != last:
        middle = first + (last - first) // 2
        if out_of_order(value, a[middle]):  # a[middle] < value
            first = middle + 1
        else:
            last = middle
    return first

# %% ../../nbs/02_sequences/04_sorting/02_insertion-point.ipynb #865adef4
from ..ordering import out_of_order

def upper_bound(a, first, last, value):
    """
    Returns the first index in [first, last) after value.
    """
    while first != last:
        middle = first + (last - first) // 2
        if out_of_order(a[middle], value):  # value < a[middle]
            last = middle
        else:
            first = middle + 1
    return first

# %% ../../nbs/02_sequences/04_sorting/02_insertion-point.ipynb #2ae56efd
def equal_range(a, first, last, value):
    """
    Returns the indexes of the slice equivalent to value.
    """
    left = lower_bound(a, first, last, value)
    right = upper_bound(a, left, last, value)
    return left, right

